320	    /// Like add_child, but takes a full path and returns an IgnoreInner.
321	    fn add_child_path(&self, dir: &Path) -> (IgnoreInner, Option<Error>) {
322	        self.add_child_path_with_found_ignore_files(dir, None)
323	    }
324	
325	    fn collect_ignore_files(
326	        &self,
327	        entries: &[fs::DirEntry],
328	    ) -> IgnoreFilesFound {
329	        let custom_ignore_filenames = &self.inner.custom_ignore_filenames;
330	        let mut files = IgnoreFilesFound {
331	            has_ignore: false,
332	            has_git_ignore: false,
333	            has_git_dir: false,
334	            has_jj_dir: false,
335	            custom_ignore_files: vec![false; custom_ignore_filenames.len()],
336	        };
337	        for entry in entries {
338	            let file_name = entry.file_name();
339	            if file_name == OsStr::new(".ignore") {
340	                files.has_ignore = true;
341	            } else if file_name == OsStr::new(".gitignore") {
342	                files.has_git_ignore = true;
343	            } else if file_name == OsStr::new(".git") {
344	                files.has_git_dir = true;
345	            } else if file_name == OsStr::new(".jj") {
346	                files.has_jj_dir = true;
347	            }
348	            for (i, name) in custom_ignore_filenames.iter().enumerate() {
349	                if file_name == name.as_os_str() {
350	                    files.custom_ignore_files[i] = true;
351	                }
352	            }
353	        }
354	        files
355	    }
356	
357	    fn add_child_path_with_found_ignore_files(
358	        &self,
359	        dir: &Path,
360	        ignore_files_list: Option<&IgnoreFilesFound>,
361	    ) -> (IgnoreInner, Option<Error>) {
362	        let check_vcs_dir = self.inner.opts.require_git
363	            && (self.inner.opts.git_ignore || self.inner.opts.git_exclude);
364	        let git_type = if check_vcs_dir
365	            && ignore_files_list.is_none_or(|i| i.has_git_dir)
366	        {
367	            dir.join(".git").metadata().ok().map(|md| md.file_type())
368	        } else {
369	            None
370	        };
371	        let has_jj = check_vcs_dir
372	            && ignore_files_list.is_none_or(|i| i.has_jj_dir)
373	            && dir.join(".jj").exists();
374	        let has_git = check_vcs_dir && (git_type.is_some() || has_jj);
375	
376	        let mut errs = PartialErrorBuilder::default();
377	        let custom_ig_matcher = if self
378	            .inner
379	            .custom_ignore_filenames
380	            .is_empty()
381	        {
382	            Gitignore::empty()
383	        } else {
384	            let custom_ignore_names: Vec<&OsString> = match ignore_files_list {
385	                None => self.inner.custom_ignore_filenames.iter().collect(),
386	                Some(m) => self
387	                    .inner
388	                    .custom_ignore_filenames
389	                    .iter()
390	                    .zip(m.custom_ignore_files.iter())
391	                    .filter(|&(_, &matched)| matched)
392	                    .map(|(name, _)| name)
393	                    .collect(),
394	            };
395	            if custom_ignore_names.is_empty() {
396	                Gitignore::empty()
397	            } else {
398	                let (m, err) = create_gitignore(
399	                    &dir,
400	                    &dir,
401	                    &custom_ignore_names,
402	                    self.inner.opts.ignore_case_insensitive,
403	                );
404	                errs.maybe_push(err);
405	                m
406	            }
407	        };
408	        let ig_matcher = if !self.inner.opts.ignore
409	            || !ignore_files_list.is_none_or(|i| i.has_ignore)
410	        {
411	            Gitignore::empty()
412	        } else {
413	            let (m, err) = create_gitignore(
414	                &dir,
415	                &dir,
416	                &[".ignore"],
417	                self.inner.opts.ignore_case_insensitive,
418	            );
419	            errs.maybe_push(err);
420	            m
421	        };
422	        let gi_matcher = if !self.inner.opts.git_ignore
423	            || !ignore_files_list.is_none_or(|i| i.has_git_ignore)
424	        {
425	            Gitignore::empty()
426	        } else {
427	            let (m, err) = create_gitignore(
428	                &dir,
429	                &dir,
430	                &[".gitignore"],
431	                self.inner.opts.ignore_case_insensitive,
432	            );
433	            errs.maybe_push(err);
434	            m
435	        };
436	
437	        let gi_exclude_matcher = if !self.inner.opts.git_exclude
438	            || !ignore_files_list.is_none_or(|i| i.has_git_dir)
439	        {
440	            Gitignore::empty()
441	        } else {
442	            match resolve_git_commondir(dir, git_type) {
443	                Ok(git_dir) => {
444	                    let (m, err) = create_gitignore(
445	                        &dir,
446	                        &git_dir,
447	                        &["info/exclude"],
448	                        self.inner.opts.ignore_case_insensitive,
449	                    );
450	                    errs.maybe_push(err);
451	                    m
452	                }
453	                Err(err) => {
454	                    errs.maybe_push(err);
455	                    Gitignore::empty()
456	                }
457	            }
458	        };
459	        let ig = IgnoreInner {
460	            compiled: self.inner.compiled.clone(),
461	            dir: dir.to_path_buf(),
462	            overrides: self.inner.overrides.clone(),
463	            types: self.inner.types.clone(),
464	            parent: Some(self.inner.clone()),
465	            is_absolute_parent: false,
466	            global_gitignores_relative_to: self
467	                .inner
468	                .global_gitignores_relative_to
469	                .clone(),
470	            explicit_ignores: self.inner.explicit_ignores.clone(),
471	            custom_ignore_filenames: self
472	                .inner
473	                .custom_ignore_filenames
474	                .clone(),
475	            custom_ignore_matcher: custom_ig_matcher,
476	            ignore_matcher: ig_matcher,
477	            git_global_matcher: self.inner.git_global_matcher.clone(),
478	            git_ignore_matcher: gi_matcher,
479	            git_exclude_matcher: gi_exclude_matcher,
480	            has_git,
481	            opts: self.inner.opts,
482	        };
483	        (ig, errs.into_error_option())
484	    }
