502	    pub(crate) fn matched_dir_entry<'a>(
503	        &'a self,
504	        dent: &DirEntry,
505	    ) -> Match<IgnoreMatch<'a>> {
506	        let m = self.matched(dent.path(), dent.is_dir());
507	        if m.is_none() && self.inner.opts.hidden && is_hidden_entry(dent) {
508	            return Match::Ignore(IgnoreMatch::hidden());
