513	    /// Returns a match indicating whether the given file path should be
514	    /// ignored or not.
515	    ///
516	    /// The match contains information about its origin.
517	    pub(crate) fn matched<'a, P: AsRef<Path>>(
518	        &'a self,
519	        path: P,
520	        is_dir: bool,
521	    ) -> Match<IgnoreMatch<'a>> {
522	        // We need to be careful with our path. If it has a leading ./, then
523	        // strip it because it causes nothing but trouble.
524	        let mut path = path.as_ref();
525	        if let Some(p) = strip_prefix("./", path) {
526	            path = p;
527	        }
528	        // Match against the override patterns. If an override matches
529	        // regardless of whether it's whitelist/ignore, then we quit and
530	        // return that result immediately. Overrides have the highest
531	        // precedence.
532	        if !self.inner.overrides.is_empty() {
533	            let mat = self
534	                .inner
535	                .overrides
536	                .matched(path, is_dir)
537	                .map(IgnoreMatch::overrides);
538	            if !mat.is_none() {
539	                return mat;
540	            }
541	        }
542	        let mut whitelisted = Match::None;
543	        if self.has_any_ignore_rules() {
544	            let mat = self.matched_ignore(path, is_dir);
545	            if mat.is_ignore() {
546	                return mat;
547	            } else if mat.is_whitelist() {
548	                whitelisted = mat;
549	            }
550	        }
551	        if !self.inner.types.is_empty() {
552	            let mat =
553	                self.inner.types.matched(path, is_dir).map(IgnoreMatch::types);
554	            if mat.is_ignore() {
555	                return mat;
556	            } else if mat.is_whitelist() {
557	                whitelisted = mat;
558	            }
559	        }
560	        whitelisted
561	    }
