563	    /// Performs matching only on the ignore files for this directory and
564	    /// all parent directories.
565	    pub(crate) fn matched_ignore<'a>(
566	        &'a self,
567	        path: &Path,
568	        is_dir: bool,
569	    ) -> Match<IgnoreMatch<'a>> {
570	        let (
571	            mut m_custom_ignore,
572	            mut m_ignore,
573	            mut m_gi,
574	            mut m_gi_exclude,
575	            mut m_explicit,
576	        ) = (Match::None, Match::None, Match::None, Match::None, Match::None);
577	        let any_git = !self.inner.opts.require_git
578	            || self.parents().any(|ig| ig.inner.has_git);
579	        let mut saw_git = false;
580	        for ig in self.parents().take_while(|ig| !ig.inner.is_absolute_parent)
581	        {
582	            if m_custom_ignore.is_none() {
583	                m_custom_ignore = ig
584	                    .inner
585	                    .custom_ignore_matcher
586	                    .matched(path, is_dir)
587	                    .map(IgnoreMatch::gitignore);
588	            }
589	            if m_ignore.is_none() {
590	                m_ignore = ig
591	                    .inner
592	                    .ignore_matcher
593	                    .matched(path, is_dir)
594	                    .map(IgnoreMatch::gitignore);
595	            }
596	            if any_git && !saw_git && m_gi.is_none() {
597	                m_gi = ig
598	                    .inner
599	                    .git_ignore_matcher
600	                    .matched(path, is_dir)
601	                    .map(IgnoreMatch::gitignore);
602	            }
603	            if any_git && !saw_git && m_gi_exclude.is_none() {
604	                m_gi_exclude = ig
605	                    .inner
606	                    .git_exclude_matcher
607	                    .matched(path, is_dir)
608	                    .map(IgnoreMatch::gitignore);
609	            }
610	            saw_git = saw_git || ig.inner.has_git;
611	        }
612	        if self.inner.opts.parents {
613	            if let Some(abs_parent_path) = self.absolute_base() {
614	                // What we want to do here is take the absolute base path of
615	                // this directory and join it with the path we're searching.
616	                // The main issue we want to avoid is accidentally duplicating
617	                // directory components, so we try to strip any common prefix
618	                // off of `path`. Overall, this seems a little ham-fisted, but
619	                // it does fix a nasty bug. It should do fine until we overhaul
620	                // this crate.
621	                let path = abs_parent_path.join(
622	                    self.parents()
623	                        .take_while(|ig| !ig.inner.is_absolute_parent)
624	                        .last()
625	                        .map_or(path, |ig| {
626	                            // This is a weird special case when ripgrep users
627	                            // search with just a `.`, as some tools do
628	                            // automatically (like consult). In this case, if
629	                            // we don't bail out now, the code below will strip
630	                            // a leading `.` from `path`, which might mangle
631	                            // a hidden file name!
632	                            if ig.inner.dir.as_path() == Path::new(".") {
633	                                return path;
634	                            }
635	                            let without_dot_slash = strip_if_is_prefix(
636	                                "./",
637	                                ig.inner.dir.as_path(),
638	                            );
639	                            let relative_base =
640	                                strip_if_is_prefix(without_dot_slash, path);
641	                            strip_if_is_prefix("/", relative_base)
642	                        }),
643	                );
644	
645	                for ig in self
646	                    .parents()
647	                    .skip_while(|ig| !ig.inner.is_absolute_parent)
648	                {
649	                    if m_custom_ignore.is_none() {
650	                        m_custom_ignore = ig
651	                            .inner
652	                            .custom_ignore_matcher
653	                            .matched(&path, is_dir)
654	                            .map(IgnoreMatch::gitignore);
655	                    }
656	                    if m_ignore.is_none() {
657	                        m_ignore = ig
658	                            .inner
659	                            .ignore_matcher
660	                            .matched(&path, is_dir)
661	                            .map(IgnoreMatch::gitignore);
662	                    }
663	                    if any_git && !saw_git && m_gi.is_none() {
664	                        m_gi = ig
665	                            .inner
666	                            .git_ignore_matcher
667	                            .matched(&path, is_dir)
668	                            .map(IgnoreMatch::gitignore);
669	                    }
670	                    if any_git && !saw_git && m_gi_exclude.is_none() {
671	                        m_gi_exclude = ig
672	                            .inner
673	                            .git_exclude_matcher
674	                            .matched(&path, is_dir)
675	                            .map(IgnoreMatch::gitignore);
676	                    }
677	                    saw_git = saw_git || ig.inner.has_git;
678	                }
679	            }
680	        }
681	        for gi in self.inner.explicit_ignores.iter().rev() {
682	            if !m_explicit.is_none() {
683	                break;
684	            }
685	            m_explicit = gi.matched(&path, is_dir).map(IgnoreMatch::gitignore);
686	        }
687	        let m_global = if any_git {
688	            self.inner
689	                .git_global_matcher
690	                .matched(&path, is_dir)
691	                .map(IgnoreMatch::gitignore)
692	        } else {
693	            Match::None
694	        };
695	
696	        m_custom_ignore
697	            .or(m_ignore)
698	            .or(m_gi)
699	            .or(m_gi_exclude)
700	            .or(m_global)
701	            .or(m_explicit)
702	    }
