1025	/// Creates a new gitignore matcher for the directory given.
1026	///
1027	/// The matcher is meant to match files below `dir`.
1028	/// Ignore globs are extracted from each of the file names relative to
1029	/// `dir_for_ignorefile` in the order given (earlier names have lower
1030	/// precedence than later names).
1031	///
1032	/// I/O errors are ignored.
1033	pub(crate) fn create_gitignore<T: AsRef<OsStr>>(
1034	    dir: &Path,
1035	    dir_for_ignorefile: &Path,
1036	    names: &[T],
1037	    case_insensitive: bool,
1038	) -> (Gitignore, Option<Error>) {
1039	    let mut builder = GitignoreBuilder::new(dir);
1040	    let mut errs = PartialErrorBuilder::default();
1041	    builder.case_insensitive(case_insensitive).unwrap();
1042	    for name in names {
1043	        let gipath = dir_for_ignorefile.join(name.as_ref());
1044	        // This check is not necessary, but is added for performance. Namely,
1045	        // a simple stat call checking for existence can often be just a bit
1046	        // quicker than actually trying to open a file. Since the number of
1047	        // directories without ignore files likely greatly exceeds the number
1048	        // with ignore files, this check generally makes sense.
1049	        //
1050	        // However, until demonstrated otherwise, we speculatively do not do
1051	        // this on Windows since Windows is notorious for having slow file
1052	        // system operations. Namely, it's not clear whether this analysis
1053	        // makes sense on Windows.
1054	        //
1055	        // For more details: https://github.com/BurntSushi/ripgrep/pull/1381
1056	        if cfg!(windows) || gipath.exists() {
1057	            errs.maybe_push_ignore_io(builder.add(gipath));
1058	        }
1059	    }
1060	    let gi = match builder.build() {
1061	        Ok(gi) => gi,
1062	        Err(err) => {
1063	            errs.push(err);
1064	            GitignoreBuilder::new(dir).build().unwrap()
1065	        }
1066	    };
1067	    (gi, errs.into_error_option())
1068	}
