1070	/// Find the GIT_COMMON_DIR for the given git worktree.
1071	///
1072	/// This is the directory that may contain a private ignore file
1073	/// "info/exclude". Unlike git, this function does *not* read environment
1074	/// variables GIT_DIR and GIT_COMMON_DIR, because it is not clear how to use
1075	/// them when multiple repositories are searched.
1076	///
1077	/// Some I/O errors are ignored.
1078	fn resolve_git_commondir(
1079	    dir: &Path,
1080	    git_type: Option<FileType>,
1081	) -> Result<PathBuf, Option<Error>> {
1082	    let git_dir_path = || dir.join(".git");
1083	    let git_dir = git_dir_path();
1084	    if !git_type.map_or(false, |ft| ft.is_file()) {
1085	        return Ok(git_dir);
1086	    }
1087	    let file = match File::open(git_dir) {
1088	        Ok(file) => io::BufReader::new(file),
1089	        Err(err) => {
1090	            return Err(Some(Error::Io(err).with_path(git_dir_path())));
1091	        }
1092	    };
1093	    let dot_git_line = match file.lines().next() {
1094	        Some(Ok(line)) => line,
1095	        Some(Err(err)) => {
1096	            return Err(Some(Error::Io(err).with_path(git_dir_path())));
1097	        }
1098	        None => return Err(None),
1099	    };
1100	    if !dot_git_line.starts_with("gitdir: ") {
1101	        return Err(None);
1102	    }
1103	    let real_git_dir = PathBuf::from(&dot_git_line["gitdir: ".len()..]);
1104	    let git_commondir_file = || real_git_dir.join("commondir");
1105	    let file = match File::open(git_commondir_file()) {
1106	        Ok(file) => io::BufReader::new(file),
1107	        Err(_) => return Err(None),
1108	    };
1109	    let commondir_line = match file.lines().next() {
1110	        Some(Ok(line)) => line,
1111	        Some(Err(err)) => {
1112	            return Err(Some(Error::Io(err).with_path(git_commondir_file())));
1113	        }
1114	        None => return Err(None),
1115	    };
1116	    let commondir_abs = if commondir_line.starts_with(".") {
1117	        real_git_dir.join(commondir_line) // relative commondir
1118	    } else {
1119	        PathBuf::from(commondir_line)
1120	    };
1121	    Ok(commondir_abs)
1122	}
