288	        let depth = err.depth();
289	        if let (Some(anc), Some(child)) = (err.loop_ancestor(), err.path()) {
290	            return Error::WithDepth {
291	                depth,
292	                err: Box::new(Error::Loop {
293	                    ancestor: anc.to_path_buf(),
294	                    child: child.to_path_buf(),
295	                }),
296	            };
297	        }
298	        let path = err.path().map(|p| p.to_path_buf());
299	        let mut ig_err = Error::WithDepth {
300	            depth,
301	            err: Box::new(Error::Io(std::io::Error::from(err))),
302	        };
303	        if let Some(path) = path {
304	            ig_err = Error::WithPath { path, err: Box::new(ig_err) };
305	        }
306	        ig_err
307	    }
