431	            Match::None => true,
432	            Match::Ignore(_) | Match::Whitelist(_) => false,
433	        }
434	    }
435	
436	    /// Returns true if the match result implies the path should be ignored.
437	    pub fn is_ignore(&self) -> bool {
438	        match *self {
439	            Match::Ignore(_) => true,
440	            Match::None | Match::Whitelist(_) => false,
441	        }
442	    }
