454	    /// `Whitelist` becomes `Ignore`. A non-match remains the same.
455	    pub fn invert(self) -> Match<T> {
456	        match self {
457	            Match::None => Match::None,
458	            Match::Ignore(t) => Match::Whitelist(t),
459	            Match::Whitelist(t) => Match::Ignore(t),
460	        }
461	    }
462	
463	    /// Return the value inside this match if it exists.
464	    pub fn inner(&self) -> Option<&T> {
465	        match *self {
466	            Match::None => None,
467	            Match::Ignore(ref t) => Some(t),
468	            Match::Whitelist(ref t) => Some(t),
469	        }
470	    }
471	
472	    /// Apply the given function to the value inside this match.
473	    ///
474	    /// If the match has no value, then return the match unchanged.
475	    pub fn map<U, F: FnOnce(T) -> U>(self, f: F) -> Match<U> {
476	        match self {
477	            Match::None => Match::None,
478	            Match::Ignore(t) => Match::Ignore(f(t)),
479	            Match::Whitelist(t) => Match::Whitelist(f(t)),
480	        }
481	    }
482	
483	    /// Return the match if it is not none. Otherwise, return other.
484	    pub fn or(self, other: Self) -> Self {
485	        if self.is_none() { other } else { self }
486	    }
